// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.promotion;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class PromotionDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        GcPressureReporter reporter = new GcPressureReporter();
        reporter.report("startup");

        StatementGenerator generator = new StatementGenerator();

        // Each statement allocates a LARGE short-lived buffer. If Survivor spaces
        // are too small, these overflow and are PROMOTED prematurely to Old gen.
        long checksum = 0;
        for (int i = 0; i < 20_000; i++) {
            byte[] statement = generator.generate("SAV2001", 512 * 1024); // 512KB transient
            checksum += statement[0];   // touch it; then it becomes garbage
        }
        long cs = checksum;
        reporter.report("after generating 20,000 large statements");
        log.info(() -> "checksum=" + cs + " (statements were short-lived buffers)");

        log.info(() -> "Diagnose with: -Xlog:gc+age=trace  (watch survivor overflow / threshold)");
        log.info(() -> "Fix: larger Young gen (-Xmn), smaller -XX:SurvivorRatio (bigger survivors),");
        log.info(() -> "     and/or stop allocating giant transient buffers (reuse / stream)");
    }
}

// ─── Would be in StatementGenerator.java (large short-lived allocations) ───
class StatementGenerator {
    // Allocates a transient buffer sized like a rendered statement.
    // Too-large buffers may bypass Young gen or overflow Survivor spaces.
    byte[] generate(String accountId, int sizeBytes) {
        byte[] buf = new byte[sizeBytes];
        buf[0] = (byte) accountId.length(); // minimal touch to avoid dead-code elimination
        return buf; // caller lets it die → should be reclaimed by a Minor GC
    }
}

// ─── Would be in GcPressureReporter.java (old-gen collection pressure) ───
class GcPressureReporter {
    private static final Logger log = Logger.getLogger("BankLog");

    void report(String phase) {
        long oldCount = 0, oldMs = 0, youngCount = 0;
        for (java.lang.management.GarbageCollectorMXBean gc :
                java.lang.management.ManagementFactory.getGarbageCollectorMXBeans()) {
            String n = gc.getName();
            boolean young = n.contains("Young") || n.contains("Scavenge")
                    || n.contains("ParNew") || n.contains("Copy");
            if (young) youngCount += gc.getCollectionCount();
            else { oldCount += gc.getCollectionCount(); oldMs += gc.getCollectionTime(); }
        }
        long yc = youngCount, oc = oldCount, om = oldMs;
        log.info(() -> "[" + phase + "] young GCs=" + yc + " | OLD GCs=" + oc
                + " oldPause=" + om + "ms  (high OLD count = likely premature promotion)");
    }
}
